mapper.select:
SELECT id, rulego_id, chain_name, description, creator_id, creator_name, status, CASE status WHEN 'draft' THEN '草稿' WHEN 'deployed' THEN '已部署' WHEN 'stopped' THEN '已停止' ELSE status END as status_desc, dsl_content, last_sync_time, create_time, update_time FROM rulego_chain
deleted = 0
AND (tenant_id = #{bo.tenantId} OR ((tenant_id IS NULL OR tenant_id = '') AND creator_id = #{bo.creatorId}))
AND creator_id = #{bo.creatorId}
AND chain_name LIKE CONCAT('%', #{bo.chainName}, '%')
AND status = #{bo.status}
AND rulego_id = #{bo.rulegoId}
ORDER BY create_time DESC
